using namespace std;

void solve() {
    string s;
    cin >> s;
    const int MOD = 998244353;
    long long ans = 0;

    // 按字母分 26 类统计
    for (int ch = 0; ch < 26; ch++) {
        long long pre = 0;
        for (int j = 1; j < (int)s.size(); j++) {
            // 中间房间增多一个，方案数翻倍
            pre = (pre * 2) % MOD;
            if (s[j - 1] - 'a' == ch) {
                // 前一个房间可以作为新的起点
                pre = (pre + 1) % MOD;
            }
            if (s[j] - 'a' == ch) {
                // 当前房间为终点，累加贡献
                ans = (ans + pre) % MOD;
            }
        }
    }

    // 加上长度为 1 的游走（每个房间独自成游）
    ans = (ans + s.size()) % MOD;
    cout << ans << endl;
}

